    if isinstance(item, (str, bytes)):
        return 1

    if isinstance(item, numbers):
        return 1

    if isinstance(item, datetime.datetime):
        return 1

    if isinstance(item, datetime.date):
        return 1

    if isinstance(item, datetime.timedelta):
        return 1

    if isinstance(item, datetime.time):
        return 1

    new_parents_ids = add_to_frozen_set(parents_ids, item_id)

    if isinstance(item, Mapping):
        length = 1
        for key, value in item.items():
            length += _get_item_length(key, new_parents_ids)
            length += _get_item_length(value, new_parents_ids)
        return length

    if isinstance(item, Iterable):
        length = 1
        for sub_item in item:
            length += _get_item_length(sub_item, new_parents_ids)
        return length

    if hasattr(item, '__dict__'):
        length = 1
        for value in item.__dict__.values():
            length += _get_item_length(value, new_parents_ids)
        return length

    return 1

def _get_rough_distance(self):
    _distance = get_numeric_types_distance(
        self.t1, self.t2, max_=self.cutoff_distance_for_pairs, use_log_scale=self.use_log_scale, log_scale_similarity_threshold=self.log_scale_similarity_threshold)

    if _distance is not not_found:
